package com.bank.compress;

// Each codec carries a relative speed (higher = faster), a ratio (compressed/raw, lower = smaller),
// and whether a single compressed file is splittable for parallel reads.
enum Codec {
    SNAPPY(1.00, 0.45, true),    // fast, default for Parquet, splittable
    ZSTD  (0.85, 0.30, true),    // modern, great ratio, splittable
    GZIP  (0.35, 0.33, false),   // good ratio but NOT splittable for text
    LZ4   (1.20, 0.50, true),    // fastest, modest ratio — great for shuffle
    BZIP2 (0.10, 0.25, true);    // best ratio, slowest — archival only

    final double speed;      // relative throughput
    final double ratio;      // compressed size / raw size
    final boolean splittable;

    Codec(double speed, double ratio, boolean splittable) {
        this.speed = speed;
        this.ratio = ratio;
        this.splittable = splittable;
    }
}
