package com.bank.compress;

import java.util.logging.Logger;

// Estimates compressed size and compress+decompress time for a raw byte size.
class CompressionProfiler {
    private static final Logger log = Logger.getLogger(CompressionProfiler.class.getName());

    private static final double BASE_MBPS = 200.0; // baseline throughput at speed=1.0

    long compressedBytes(long rawBytes, Codec codec) {
        return Math.round(rawBytes * codec.ratio);
    }

    // Simulated seconds to compress then decompress the data once.
    double roundTripSeconds(long rawBytes, Codec codec) {
        double mb = rawBytes / (1024.0 * 1024.0);
        double throughput = BASE_MBPS * codec.speed;
        return (mb / throughput) * 2; // compress + decompress
    }

    void profile(long rawBytes, Codec codec) {
        long out = compressedBytes(rawBytes, codec);
        double secs = roundTripSeconds(rawBytes, codec);
        log.info(() -> String.format("%-7s size=%,d bytes (%.0f%% of raw)  time=%.2fs  splittable=%s",
                codec, out, codec.ratio * 100, secs, codec.splittable));
    }
}
