package com.bank.compress;

import java.util.logging.Logger;

// Shows how many tasks can read a single file given splittability.
class ReadParallelismPlanner {
    private static final Logger log = Logger.getLogger(ReadParallelismPlanner.class.getName());

    private static final long SPLIT_BYTES = 128L * 1024 * 1024; // 128 MB splits

    int readTasks(long fileBytes, Codec codec) {
        if (!codec.splittable) {
            log.warning(() -> codec + " file is NOT splittable → only 1 task reads it (no parallelism)");
            return 1;
        }
        int tasks = (int) Math.max(1, Math.ceil(fileBytes / (double) SPLIT_BYTES));
        log.info(() -> codec + " file is splittable → " + tasks + " tasks read in parallel");
        return tasks;
    }
}
