package com.bank.compress;

import java.util.logging.Logger;

// Applies the INTERNAL codec (spark.io.compression.codec) to shuffle bytes.
class ShuffleLayer {
    private static final Logger log = Logger.getLogger(ShuffleLayer.class.getName());

    private final Codec internalCodec;
    private final boolean shuffleCompress;

    ShuffleLayer(Codec internalCodec, boolean shuffleCompress) {
        this.internalCodec = internalCodec;
        this.shuffleCompress = shuffleCompress;
    }

    long networkBytes(long shuffleRawBytes) {
        if (!shuffleCompress) {
            log.warning(() -> "Shuffle compression OFF — moving " + shuffleRawBytes + " raw bytes over network");
            return shuffleRawBytes;
        }
        long overWire = Math.round(shuffleRawBytes * internalCodec.ratio);
        log.info(() -> "Shuffle compressed with " + internalCodec + ": " + shuffleRawBytes
                + " → " + overWire + " bytes over network");
        return overWire;
    }
}
