package com.bank.compress;

import java.util.logging.Logger;

public class CompressionDemo {
    private static final Logger log = Logger.getLogger(CompressionDemo.class.getName());

    public static void main(String[] args) {
        long rawTradeBytes = 10L * 1024 * 1024 * 1024; // 10 GB of settled trades
        CompressionProfiler profiler = new CompressionProfiler();
        ReadParallelismPlanner planner = new ReadParallelismPlanner();

        log.info("=== Output storage: compare all codecs on 10 GB of trades ===");
        for (Codec c : Codec.values()) {
            profiler.profile(rawTradeBytes, c);
            planner.readTasks(profiler.compressedBytes(rawTradeBytes, c), c);
        }

        log.info("=== The Gzip-CSV mistake vs Snappy/ZSTD Parquet ===");
        long gzipFile = profiler.compressedBytes(rawTradeBytes, Codec.GZIP);
        planner.readTasks(gzipFile, Codec.GZIP);     // 1 task — bad
        long zstdFile = profiler.compressedBytes(rawTradeBytes, Codec.ZSTD);
        planner.readTasks(zstdFile, Codec.ZSTD);     // many tasks — good

        log.info("=== Internal shuffle compression (spark.io.compression.codec) ===");
        long shuffleRaw = 4L * 1024 * 1024 * 1024;   // 4 GB shuffle
        new ShuffleLayer(Codec.LZ4, true).networkBytes(shuffleRaw);  // fast internal codec
        new ShuffleLayer(Codec.LZ4, false).networkBytes(shuffleRaw); // compression off
    }
}
